WITH cleaned AS (SELECT *, ROUND(budget, 1) AS budget_rounded, COALESCE(location, 'N/A') AS location_clean FROM departments WHERE dept_name IS NOT NULL AND dept_name IS NOT DISTINCT FROM 'HR') SELECT s.*, x.employee_level, x.hire_date FROM cleaned s LEFT JOIN LATERAL (SELECT c.level AS employee_level, c.hire_date FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) x ON TRUE;
